//! Embed the offline documentation into `leader`.
//!
//! `scripts/docs-bundle.txt` is the single list of files that make up the docs pack (the same list
//! `scripts/pack-docs.sh` zips for the website). Each file is Deflate-compressed into OUT_DIR at build time and the
//! generated `docs_data.rs` points `include_bytes!` at those bytes. No generated file is committed, and the binary
//! carries the docs without the installer putting a single extra file on disk.
use std::fs;
use std::io::Write;
use std::path::PathBuf;

use flate2::Compression;
use flate2::write::DeflateEncoder;

fn main() {
    let crate_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let root = crate_dir.join("../../..");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
    let manifest = root.join("scripts/docs-bundle.txt");

    println!("cargo:rerun-if-changed={}", manifest.display());
    println!("cargo:rerun-if-changed={}", crate_dir.join("build.rs").display());
    let listed = fs::read_to_string(&manifest).unwrap_or_else(|e| panic!("cannot read {}: {e}", manifest.display()));
    let files: Vec<_> = listed.lines().map(str::trim).filter(|l| !l.is_empty() && !l.starts_with('#')).collect();
    assert!(!files.is_empty(), "the docs bundle is empty");

    let dir = out.join("docs");
    fs::create_dir_all(&dir).expect("create OUT_DIR/docs");
    let mut rs = String::from("// Generated by build.rs. Do not edit.\n");
    rs.push_str("pub static DOCS: &[(&str, &[u8])] = &[\n");
    for (i, rel) in files.iter().enumerate() {
        let path = root.join(rel);
        assert!(path.is_file() && !rel.contains(".."), "bad docs entry: {rel}");
        println!("cargo:rerun-if-changed={}", path.display());
        let data = fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        let mut encoder = DeflateEncoder::new(Vec::new(), Compression::best());
        encoder.write_all(&data).expect("compress docs");
        let compressed = encoder.finish().expect("finish docs compression");
        let blob = dir.join(format!("{i}.deflate"));
        fs::write(&blob, &compressed).expect("write compressed docs");
        rs.push_str(&format!("    ({:?}, include_bytes!({:?})),\n", rel, blob.to_str().expect("UTF-8 OUT_DIR")));
    }
    rs.push_str("];\n");
    fs::write(out.join("docs_data.rs"), rs).expect("write docs_data.rs");
}
